	@Test
	void borrowedCursorRetainsSourceMetricsThroughPreservationAndClose() {
		ValidatingSource backing = new ValidatingSource(true) {
			@Override
			public SnapshotReadContext acquireSnapshot(IsolationLevel level) {
				return validation.acquire(() -> new DelegatingSailDataset(super.dataset(level)) {
					@Override
					public CloseableIteration<? extends Statement> getStatements(Resource subj, IRI pred, Value obj,
							Resource... contexts) {
						return new ReportingIteration(super.getStatements(subj, pred, obj, contexts));
					}
				});
			}
		};
		backing.statements.add(ADDED);
		try (SailSourceBranch branch = new SailSourceBranch(backing);
				SailDataset view = branch.dataset(IsolationLevels.SNAPSHOT);
				CloseableIteration<? extends Statement> iteration = view.getStatements(null, P, null)) {
			IndexReportingIterator metrics = assertInstanceOf(IndexReportingIterator.class, iteration);
			assertEquals("test-index", metrics.getIndexName());
			assertEquals(0, metrics.getSourceRowsScannedActual());
			assertTrue(iteration.hasNext());
			iteration.next();
			assertEquals(2, metrics.getSourceRowsScannedActual());
			assertEquals(1, metrics.getSourceRowsMatchedActual());
			assertEquals(1, metrics.getSourceRowsFilteredActual());
			write(backing, MARKER);
			assertTrue(iteration.hasNext());
			iteration.next();
			assertFalse(iteration.hasNext());
			assertEquals("test-index", metrics.getIndexName());
			assertEquals(4, metrics.getSourceRowsScannedActual());
			assertEquals(2, metrics.getSourceRowsMatchedActual());
			assertEquals(2, metrics.getSourceRowsFilteredActual());
			iteration.close();
			assertEquals(4, metrics.getSourceRowsScannedActual(), "Buffered consumption must not add native scans");
		}
		assertEquals(0, backing.validation.retainedContextCount());
		ValidatingSource plain = new ValidatingSource(false);
		try (SnapshotReadContext context = plain.acquireSnapshot(IsolationLevels.SNAPSHOT);
				CloseableIteration<? extends Statement> iteration = context.dataset().getStatements(null, P, null)) {
			IndexReportingIterator metrics = assertInstanceOf(IndexReportingIterator.class, iteration);
			assertNull(metrics.getIndexName());
			assertEquals(-1, metrics.getSourceRowsScannedActual());
			assertEquals(-1, metrics.getSourceRowsMatchedActual());
			assertEquals(-1, metrics.getSourceRowsFilteredActual());
		}
	}

	@Test
	void acceptedChildObservationDoesNotExtendThroughDeferredRootPublication() {
		ValidatingSource backing = new ValidatingSource(true);
		try (SailSourceBranch root = new SailSourceBranch(backing, new DynamicModelFactory(), true)) {
			SailSource first = root.fork();
			SailSource second = root.fork();
			try {
				assertFalse(read(second, IsolationLevels.SNAPSHOT, ABSENT));
				assertFalse(read(first, IsolationLevels.SERIALIZABLE, ABSENT));
				write(first, MARKER);
				first.prepare();
				first.flush();
				first.close();
				assertFalse(backing.statements.contains(MARKER), "Another borrower delays physical root flush");
				write(second, ADDED);
				second.prepare();
				second.flush();
				second.close();
				assertTrue(backing.statements.contains(MARKER));
				assertTrue(backing.statements.contains(ADDED));
			} finally {
				first.close();
				second.close();
			}
			assertEquals(0, backing.validation.retainedContextCount());
			assertEquals(0, backing.validation.retainedHistoryCount());
		}
	}

