	@Test
	void closingLastHistoryOwnerDuringSiblingAcquisitionReclaimsItsEvidence() throws Exception {
		SnapshotValidationSupport.PublicationGroup group = new SnapshotValidationSupport.PublicationGroup(
				new ReentrantLock());
		ValidatingSource first = new ValidatingSource(false, group);
		ValidatingSource second = new ValidatingSource(false, group);
		SnapshotReadContext old = first.acquireSnapshot(IsolationLevels.SNAPSHOT);
		write(first, ADDED);
		assertEquals(1, first.validation.retainedHistoryCount());
		CountDownLatch acquiring = new CountDownLatch(1);
		CountDownLatch finishAcquisition = new CountDownLatch(1);
		try (ExecutorService executor = Executors.newSingleThreadExecutor()) {
			Future<SnapshotReadContext> acquisition = executor.submit(() -> second.validation.acquire(() -> {
				acquiring.countDown();
				await(finishAcquisition);
				return second.dataset(IsolationLevels.SNAPSHOT);
			}));
			await(acquiring);
			try {
				old.close();
			} finally {
				finishAcquisition.countDown();
			}
			try (SnapshotReadContext current = acquisition.get(5, TimeUnit.SECONDS)) {
				assertEquals(0, first.validation.retainedContextCount());
				assertEquals(0, first.validation.retainedHistoryCount(),
						"A sibling's acquired data handle must not retain an unowned participant's old journal");
				assertEquals(1, second.validation.retainedContextCount());
			}
		}
	}

	@Test
	void canceledTokenAcquisitionReleasesOwnershipWithoutPreparingClosedDelegate() throws Exception {
		CountDownLatch acquiring = new CountDownLatch(1);
		CountDownLatch finishAcquisition = new CountDownLatch(1);
		AtomicInteger activeTokens = new AtomicInteger();
		AtomicInteger prepares = new AtomicInteger();
		AtomicInteger closes = new AtomicInteger();
		SnapshotValidationSupport.PublicationGroup group = new SnapshotValidationSupport.PublicationGroup(() -> {
			acquiring.countDown();
			finishAcquisition.await();
			return token(activeTokens);
		});
		ValidatingSource source = new ValidatingSource(false, group);
		SailSink sink = source.validation.sink(lifecycleSink(prepares::incrementAndGet, closes), List.of());
		try (ExecutorService executor = Executors.newSingleThreadExecutor()) {
			Future<Throwable> preparation = executor.submit(() -> {
				try {
					sink.prepare();
					return null;
				} catch (Throwable failure) {
					return failure;
				}
			});
			await(acquiring);
			try {
				sink.close();
			} finally {
				finishAcquisition.countDown();
			}
			assertInstanceOf(IllegalStateException.class, preparation.get(5, TimeUnit.SECONDS));
			sink.close();
			assertEquals(0, prepares.get(), "A closed delegate cannot be prepared after canceled acquisition");
			assertEquals(1, closes.get(), "Cancellation closes the delegate exactly once");
			assertEquals(0, activeTokens.get(), "Acquisition returning after cancellation releases its token");
		}
	}

	@Test
	void tokenDelegatePrepareOwnsItsLifecycleUntilForeignCloseCanProceed() throws Exception {
		CountDownLatch preparing = new CountDownLatch(1);
		CountDownLatch finishPrepare = new CountDownLatch(1);
		CountDownLatch closing = new CountDownLatch(1);
		AtomicInteger activeTokens = new AtomicInteger();
		AtomicInteger closes = new AtomicInteger();
		SnapshotValidationSupport.PublicationGroup group = new SnapshotValidationSupport.PublicationGroup(
				() -> token(activeTokens));
		ValidatingSource source = new ValidatingSource(false, group);
		SailSink sink = source.validation.sink(lifecycleSink(() -> {
			preparing.countDown();
			await(finishPrepare);
			assertEquals(0, closes.get(), "An in-progress delegate prepare must not be closed underneath it");
		}, closes), List.of());
		try (ExecutorService executor = Executors.newFixedThreadPool(2)) {
			Future<?> preparation = executor.submit(sink::prepare);
			await(preparing);
			Future<?> cleanup = executor.submit(() -> {
				closing.countDown();
				sink.close();
			});
			await(closing);
			try {
				assertThrows(TimeoutException.class, () -> cleanup.get(1, TimeUnit.SECONDS),
						"Cleanup must wait for the held delegate operation without interrupting its reservation");
			} finally {
				finishPrepare.countDown();
				preparation.get(5, TimeUnit.SECONDS);
				cleanup.get(5, TimeUnit.SECONDS);
			}
			sink.close();
			assertEquals(1, closes.get());
			assertEquals(0, activeTokens.get());
		}
	}

	private static Lock token(AtomicInteger active) {
		active.incrementAndGet();
		return new Lock() {
			private final AtomicBoolean released = new AtomicBoolean();

			@Override
			public boolean isActive() {
				return !released.get();
			}

			@Override
			public void release() {
				assertFalse(released.getAndSet(true), "An acquired token is released exactly once");
				active.decrementAndGet();
			}
		};
	}

	private static SailSink lifecycleSink(Runnable prepare, AtomicInteger closes) {
		return new Changeset() {
			@Override
			public void prepare() {
				prepare.run();
			}

			@Override
			public void close() {
				closes.incrementAndGet();
				super.close();
			}

			@Override
			public void flush() {
			}

			@Override
			public Model createEmptyModel() {
				return new DynamicModelFactory().createEmptyModel();
			}
		};
	}

	@Test
	void reusedLegacySinkReceivesIncomingWritesAfterItsNextObservation() {
		CountingSource backing = new CountingSource();
		try (SailSourceBranch branch = new SailSourceBranch(backing);
				SailSink reused = branch.sink(IsolationLevels.SERIALIZABLE)) {
			reused.approve(MARKER);
			reused.flush();
			reused.observe(ABSENT, P, null);
			try (SailSink sibling = branch.sink(IsolationLevels.READ_COMMITTED)) {
				sibling.approve(ADDED);
				sibling.flush();
			}
			assertThrows(SailConflictException.class, reused::prepare,
					"reuse must restore legacy incoming-write notifications before recording the new observation");
		}
	}

	@Test
	void closingAFlushedObserverDoesNotWaitForASiblingsPreparedReservation() throws Exception {
		ValidatingSource backing = new ValidatingSource(false);
		try (SailSourceBranch branch = new SailSourceBranch(backing);
				SailSink observer = branch.sink(IsolationLevels.SERIALIZABLE)) {
			observer.observe(ABSENT, P, null);
			observer.flush();
			CountDownLatch prepared = new CountDownLatch(1);
			CountDownLatch finish = new CountDownLatch(1);
			try (ExecutorService executor = Executors.newFixedThreadPool(2)) {
				Future<?> writer = executor.submit(() -> {
					try (SailSink sink = branch.sink(IsolationLevels.READ_COMMITTED)) {
						sink.prepare();
						prepared.countDown();
						try {
							finish.await();
						} catch (InterruptedException interrupted) {
							Thread.currentThread().interrupt();
							throw new AssertionError(interrupted);
						}
					}
				});
				await(prepared);
				try {
					executor.submit(observer::close).get(5, TimeUnit.SECONDS);
				} finally {
					finish.countDown();
					writer.get(5, TimeUnit.SECONDS);
				}
			}
		}
	}

	@Test
	void immutableOverlaysExposeEachNonemptyContextExactlyOnce() {
		Resource graph = VF.createIRI("urn:observation:graph");
		Statement first = VF.createStatement(PRESENT.getSubject(), P, PRESENT.getObject(), graph);
		Statement second = VF.createStatement(ABSENT, P, ADDED.getObject(), graph);
		for (IsolationLevel level : List.of(IsolationLevels.READ_COMMITTED, IsolationLevels.SNAPSHOT_READ,
				IsolationLevels.SNAPSHOT, IsolationLevels.SERIALIZABLE)) {
			ValidatingSource backing = new ValidatingSource(false);
			try (SailSource branch = backing.fork()) {
				write(branch, first);
				assertEquals(List.of(graph), contexts(branch, level));
				write(branch, second);
				assertEquals(List.of(graph), contexts(branch, level), "separate overlays must not duplicate a context");
				try (SailSink sink = branch.sink(level)) {
					sink.deprecate(first);
					sink.flush();
					assertEquals(List.of(graph), contexts(branch, level), "one remaining statement keeps its context");
					sink.deprecate(second);
					sink.flush();
					assertEquals(List.of(), contexts(branch, level), "removing the last statement removes its context");
				}
				write(branch, first);
				try (SailSink sink = branch.sink(level)) {
					sink.clear(graph);
					sink.flush();
					assertEquals(List.of(), contexts(branch, level), "a context clear removes its context");
				}
				write(branch, second);
				try (SailSink sink = branch.sink(level)) {
					sink.clear();
					sink.flush();
					assertEquals(List.of(), contexts(branch, level), "a statement clear removes all contexts");
				}
				write(branch, first);
				assertEquals(List.of(graph), contexts(branch, level), "reuse after a clear restores one context");
			}
		}
	}

	private static List<Resource> contexts(SailSource source, IsolationLevel level) {
		try (SailDataset dataset = source.dataset(level);
				CloseableIteration<? extends Resource> contexts = dataset.getContextIDs()) {
			List<Resource> result = new ArrayList<>();
			while (contexts.hasNext()) {
				result.add(contexts.next());
			}
			return result;
		}
	}

