	@Test
	void warmedRootDoesNotObserveLowerTransactionBranches() {
		for (boolean autoFlush : List.of(false, true)) {
			CountingSource backing = new CountingSource();
			try (SailSourceBranch root = new SailSourceBranch(backing, new DynamicModelFactory(), autoFlush)) {
				assertTrue(read(root, IsolationLevels.SERIALIZABLE, PRESENT.getSubject()));
				root.flush();
				int observations = backing.observations;
				for (IsolationLevel level : List.of(IsolationLevels.NONE, IsolationLevels.READ_COMMITTED,
						IsolationLevels.SNAPSHOT_READ, IsolationLevels.SNAPSHOT)) {
					try (SailSource transaction = root.fork()) {
						assertTrue(read(transaction, level, PRESENT.getSubject()));
						assertFalse(read(transaction, level, ABSENT));
						transaction.flush();
					}
					root.flush();
					assertEquals(observations, backing.observations, "lower requests at " + level);
				}
			}
		}
	}

