	@Test
	void physicalOwnerRetainsClosedSinkEvidenceAndRetiresItOnDiscardOrPublication() {
		SnapshotValidationSupport.PublicationGroup group = new SnapshotValidationSupport.PublicationGroup(
				new ReentrantLock(), false, true);
		ValidatingSource backing = new ValidatingSource(false, group);
		SailSink staged = backing.sink(IsolationLevels.READ_COMMITTED);
		staged.approve(ADDED);
		assertEquals(1, group.retainedPendingPublicationCount());
		staged.close();
		assertEquals(1, group.retainedPendingPublicationCount(),
				"Wrapper close does not abort a shared native transaction");
		group.discardPendingWrites();
		group.discardPendingWrites();
		assertEquals(0, group.retainedPendingPublicationCount());
		assertEquals(0, backing.validation.retainedHistoryCount());
		try (SailSink next = backing.sink(IsolationLevels.READ_COMMITTED)) {
			next.approve(MARKER);
			assertEquals(1, group.retainedPendingPublicationCount());
			next.flush();
			assertEquals(0, group.retainedPendingPublicationCount());
			next.flush();
			assertEquals(0, group.retainedPendingPublicationCount());
		}
	}

