	@Test
	void resultCloseDoesNotWaitForAnUnrelatedPreparedReservation() throws Exception {
		ValidatingSource backing = new ValidatingSource(false);
		SnapshotReadContext snapshot = backing.acquireSnapshot(IsolationLevels.SNAPSHOT);
		CloseableIteration<? extends Statement> result = snapshot.dataset().getStatements(null, P, null);
		CountDownLatch prepared = new CountDownLatch(1);
		CountDownLatch release = new CountDownLatch(1);
		try (ExecutorService workers = Executors.newFixedThreadPool(2)) {
			Future<?> writer = workers.submit(() -> {
				try (SailSink sink = backing.sink(IsolationLevels.READ_COMMITTED)) {
					sink.prepare();
					prepared.countDown();
					await(release);
				}
			});
			try {
				assertTrue(prepared.await(5, TimeUnit.SECONDS));
				workers.submit(() -> {
					assertTrue(result.hasNext());
					result.close();
					snapshot.close();
				}).get(5, TimeUnit.SECONDS);
				assertEquals(1, backing.closedDatasets.get());
			} finally {
				release.countDown();
			}
			writer.get(5, TimeUnit.SECONDS);
		}
	}

	@Test
	void releasingTheLastContextDuringPrepareReclaimsHistoryWhenReservationCloses() throws Exception {
		for (boolean otherParticipant : new boolean[] { false, true }) {
			SnapshotValidationSupport.PublicationGroup group = new SnapshotValidationSupport.PublicationGroup(
					new ReentrantLock());
			ValidatingSource backing = new ValidatingSource(false, group);
			ValidatingSource publisher = otherParticipant ? new ValidatingSource(false, group) : backing;
			SnapshotReadContext snapshot = backing.acquireSnapshot(IsolationLevels.SNAPSHOT);
			write(backing, ADDED);
			assertEquals(1, backing.validation.retainedHistoryCount());
			try (SailSink prepared = publisher.sink(IsolationLevels.READ_COMMITTED);
					ExecutorService closer = Executors.newSingleThreadExecutor()) {
				prepared.prepare();
				closer.submit(snapshot::close).get(5, TimeUnit.SECONDS);
				assertEquals(0, backing.validation.retainedContextCount());
			}
			assertEquals(0, backing.validation.retainedHistoryCount(),
					"closing the reservation must finish reclamation deferred by the result-closing thread");
		}
	}

	@Test
	void immutableReadersDoNotShareThePublicationReservation() throws Exception {
		ValidatingSource backing = new ValidatingSource(false);
		CountDownLatch firstReading = new CountDownLatch(1);
		CountDownLatch release = new CountDownLatch(1);
		backing.beforeRead = subject -> {
			if (PRESENT.getSubject().equals(subject)) {
				firstReading.countDown();
				await(release);
			}
		};
		try (SnapshotReadContext first = backing.acquireSnapshot(IsolationLevels.SNAPSHOT);
				SnapshotReadContext second = backing.acquireSnapshot(IsolationLevels.SNAPSHOT);
				ExecutorService workers = Executors.newFixedThreadPool(2)) {
			Future<?> blocked = workers.submit(() -> assertEquals(1, count(first.dataset(), PRESENT.getSubject())));
			try {
				assertTrue(firstReading.await(5, TimeUnit.SECONDS));
				assertEquals(0, workers.submit(() -> count(second.dataset(), ABSENT)).get(5, TimeUnit.SECONDS));
			} finally {
				release.countDown();
			}
			blocked.get(5, TimeUnit.SECONDS);
		}
	}

	@Test
	void publicationPinsTheSelectedBackingBeforeConcurrentClose() throws Exception {
		ValidatingSource backing = new ValidatingSource(true);
		SnapshotReadContext snapshot = backing.acquireSnapshot(IsolationLevels.SNAPSHOT);
		CountDownLatch inverseReading = new CountDownLatch(1);
		CountDownLatch release = new CountDownLatch(1);
		backing.beforeRead = subject -> {
			if (ABSENT.equals(subject)) {
				inverseReading.countDown();
				await(release);
			}
		};
		try (ExecutorService workers = Executors.newSingleThreadExecutor()) {
			Future<?> writer = workers.submit(() -> write(backing, ADDED));
			try {
				assertTrue(inverseReading.await(5, TimeUnit.SECONDS));
				snapshot.close();
				assertEquals(0, backing.closedDatasets.get(),
						"publication owns the selected backing until mutation completes");
			} finally {
				release.countDown();
			}
			writer.get(5, TimeUnit.SECONDS);
			assertEquals(1, backing.closedDatasets.get());
			assertEquals(0, backing.validation.retainedContextCount());
			assertEquals(0, backing.validation.retainedHistoryCount());
		}
	}

