	@Test
	void failedSharedContextAcquisitionTransfersBorrowedOwnershipToTheSource() {
		IllegalStateException primary = new IllegalStateException("context version acquisition failed");
		AtomicInteger failedOwnerCloses = new AtomicInteger();
		SharedValidatingSource backing = new SharedValidatingSource() {
			private final SnapshotValidationSupport failing = new SnapshotValidationSupport(this, new ReentrantLock(),
					true, () -> {
						throw primary;
					});
			private boolean fail = true;

			@Override
			public SnapshotReadContext acquireSnapshot(IsolationLevel level, SailDataset borrowedHandle) {
				if (fail) {
					fail = false;
					return failing.acquire(() -> new DelegatingSailDataset(borrowedHandle) {
						@Override
						public void close() {
							failedOwnerCloses.incrementAndGet();
							super.close();
						}
					});
				}
				return super.acquireSnapshot(level, borrowedHandle);
			}
		};
		try (SailSourceBranch root = new SailSourceBranch(backing, new DynamicModelFactory(), true)) {
			assertEquals(primary, assertThrows(IllegalStateException.class,
					() -> root.acquireSnapshot(IsolationLevels.SNAPSHOT)));
			assertEquals(1, failedOwnerCloses.get());
			assertEquals(0, backing.validation.retainedContextCount());
			assertEquals(0, backing.closedDatasets.get());
			assertTrue(read(root, IsolationLevels.SNAPSHOT, PRESENT.getSubject()));
			assertEquals(1, backing.acquiredDatasets.get(), "a failed borrower must leave the cached resource usable");
		}
		assertEquals(1, backing.closedDatasets.get());
	}

