					SnapshotObservation earlier = new SnapshotObservation(first, new Object(), Set.of(
							new Changeset.SimpleStatementPattern(ABSENT, P, null, null, true)));
					SnapshotObservation later = new SnapshotObservation(second, new Object(), Set.of(
							new Changeset.SimpleStatementPattern(null, Q, null, null, true)));
