				try (SailSink sink = capable.sink(IsolationLevels.SERIALIZABLE, List.of(earlier))) {
					sink.flush();
				}
				try (SailSink sink = capable.sink(IsolationLevels.SERIALIZABLE, List.of(later))) {
					sink.approve(MARKER);
					sink.flush();
				}
				child.flush();
				assertThrows(SailConflictException.class, root::prepare,
						"compression and transfer must not bind the earlier read to the later origin");
